#include <vector>
#include <cstddef>
#include <cmath>
#include <algorithm>
#include <omp.h>

struct COOElement {
   size_t row, column;
   double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Uses a parallel Jacobi iteration (works for diagonally dominant / well-conditioned cases).
*/
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    x.assign(N, 0.0);
    if (N == 0) return;

    // Build per-row structure for fast Jacobi updates: diagonal and off-diagonals.
    std::vector<double> diag(N, 0.0);
    std::vector<std::vector<std::pair<size_t,double>>> off(N);
    off.assign(N, {});

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) continue; // ignore invalid entries
        if (e.row == e.column) {
            diag[e.row] += e.value; // allow multiple diagonal entries by summing
        } else {
            off[e.row].push_back({e.column, e.value});
        }
    }

    // If any diagonal is zero, Jacobi cannot proceed robustly; keep x as zeros.
    // (Could be extended with pivoting/GS/CG, but not requested.)
    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) return;
    }

    std::vector<double> xnew(N, 0.0);

    // Iteration controls
    const size_t maxIters = 10000;
    const double relTol = 1e-12;
    const double absTol = 1e-14;

    // Norm of b for relative stopping
    double b2 = 0.0;
    #pragma omp parallel for reduction(+:b2) schedule(static)
    for (size_t i = 0; i < N; ++i) b2 += b[i] * b[i];
    const double bNorm = std::sqrt(b2);

    for (size_t iter = 0; iter < maxIters; ++iter) {
        // Compute xnew = D^{-1}(b - (L+U)x)
        #pragma omp parallel for schedule(static)
        for (size_t i = 0; i < N; ++i) {
            double sum = 0.0;
            for (auto const& kv : off[i]) {
                sum += kv.second * x[kv.first];
            }
            xnew[i] = (b[i] - sum) / diag[i];
        }

        // Check convergence: ||xnew - x|| relative to ||xnew|| (and absolute)
        double diff2 = 0.0, xn2 = 0.0;
        #pragma omp parallel for reduction(+:diff2,xn2) schedule(static)
        for (size_t i = 0; i < N; ++i) {
            const double d = xnew[i] - x[i];
            diff2 += d * d;
            xn2   += xnew[i] * xnew[i];
        }

        const double diff = std::sqrt(diff2);
        const double xn   = std::sqrt(xn2);
        const double denom = std::max({1.0, xn, bNorm});

        // Update x
        x.swap(xnew);

        if (diff <= absTol || diff / denom <= relTol) {
            break;
        }
    }
}
